/*
 * replay-core.test.js -- plain-Node tests for the replay logic (no framework).
 *
 * Run from the repository root:
 *
 *     node web/tests/replay-core.test.js
 *
 * The fixtures in tests/fixtures/replay/ are generated by the Python engine
 * (`python -m tools.make_replay_fixtures`), so this checks the JavaScript timeline
 * against the engine, ply by ply, for every committed sample game.
 */
"use strict";

const assert = require("node:assert");
const fs = require("node:fs");
const path = require("node:path");

const core = require("../replay-core.js");

const ROOT = path.join(__dirname, "..", "..");
const FIXTURES = path.join(ROOT, "tests", "fixtures", "replay", "replay_fixtures.json");

let checks = 0;

function check(condition, message) {
  assert.ok(condition, message);
  checks += 1;
}

function loadJson(relativePath) {
  return JSON.parse(fs.readFileSync(path.join(ROOT, relativePath), "utf8"));
}

// ---------------------------------------------------------------------------
// Timeline versus the engine-generated fixtures
// ---------------------------------------------------------------------------

const fixtures = loadJson("tests/fixtures/replay/replay_fixtures.json");
check(fixtures.samples.length >= 6, "fixtures should cover every sample game");

for (const sample of fixtures.samples) {
  const game = loadJson(sample.file);
  const timeline = core.buildTimeline(game);

  check(
    timeline.states.length === sample.timeline.length,
    sample.file + ": expected " + sample.timeline.length + " states, got " + timeline.states.length,
  );
  check(
    timeline.openingCount === sample.opening_count,
    sample.file + ": expected " + sample.opening_count + " opening plies, got " + timeline.openingCount,
  );
  check(
    timeline.plies.length === timeline.states.length - 1,
    sample.file + ": one ply record per transition",
  );

  sample.timeline.forEach((expected, index) => {
    const actual = core.stateToFen(timeline.states[index]);
    check(actual === expected, sample.file + " ply " + index + ": expected " + expected + ", got " + actual);
  });

  // Rebuilding must be pure: the game object is not modified.
  check(
    JSON.stringify(core.buildTimeline(game).states) === JSON.stringify(timeline.states),
    sample.file + ": buildTimeline is deterministic",
  );
}

// ---------------------------------------------------------------------------
// Move application errors
// ---------------------------------------------------------------------------

const tinyFen = "4k4/9/9/9/9/9/9/9/9/4K4 w - - 0 1";
const tiny = core.parseFen(tinyFen);

assert.throws(() => core.applyMove(tiny, "a0a1"), /from square is empty/);
assert.throws(() => core.applyMove(tiny, "e0e0"), /same square/);
assert.throws(() => core.applyMove(tiny, "e0j1"), /off the board/);
assert.throws(() => core.applyMove(tiny, "e0a9x"), /four characters/);
assert.throws(() => core.parseFen("9/9/9 w - - 0 1"), /10 ranks/);
assert.throws(() => core.parseFen("9/9/9/9/9/9/9/9/9/x8 w - - 0 1"), /unknown piece/);

// The error names the ply, counting from 1 after the starting position.
assert.throws(
  () => core.buildTimeline({ start_fen: tinyFen, moves: [{ move: "a0a1" }] }),
  /ply 1: the from square is empty/,
);
assert.throws(() => core.buildTimeline({ start_fen: tinyFen }), /no moves array/);
assert.throws(() => core.buildTimeline({ moves: [] }), /start_fen/);

// applyMove must not modify its input state.
const before = core.stateToFen(tiny);
const after = core.applyMove(tiny, "e0e1");
check(core.stateToFen(tiny) === before, "applyMove leaves the input untouched");
check(core.stateToFen(after) !== before, "applyMove returns the new position");
check(after.sideToMove === "b", "applyMove flips the side to move");

// An opening segment that does not land on start_fen is dropped, not trusted.
const fallback = core.buildTimeline({
  start_fen: tinyFen,
  opening_moves: ["a0a1"],
  moves: [],
});
check(fallback.openingCount === 0 && fallback.source === "start_fen", "bad opening falls back");
check(fallback.states.length === 1, "fallback timeline starts at start_fen");

// ---------------------------------------------------------------------------
// Display helpers
// ---------------------------------------------------------------------------

check(core.playerName({ type: "human" }) === "Human", "human spec");
check(core.playerName("human") === "human", "plain string spec");
check(core.playerName({ type: "scripted", params: {} }) === "Scripted", "scripted spec");
check(
  core.playerName({ type: "alphabeta", params: { depth: 3, evaluator: "full" } }).includes("depth 3"),
  "alphabeta name includes its depth",
);
check(core.resultLabel("black_win") === "Black wins", "result label");
check(core.reasonLabel("perpetual_check") === "perpetual check", "reason label");
check(
  core.bannerText({ result: "black_win", reason: "perpetual_check" }) ===
    "Black wins · perpetual check",
  "banner text",
);
check(core.resultLabel("something_new") === "something_new", "unknown results pass through");

const details = core.moveDetails({ time_ms: 12.34, nodes: 4521, depth: 4, eval: 35 });
check(details.length === 4 && details[3] === "eval 35", "per-move details");
check(core.moveDetails(null).length === 0, "missing details are omitted");

console.log("replay-core: " + checks + " checks passed across " + fixtures.samples.length + " samples");
